import json, sys

def summarize_text(s, n=400):
    s = s.replace("\n", " \\n ")
    if len(s) > n:
        return s[:n] + f"...[{len(s)} chars]"
    return s

def content_summary(content):
    out = []
    if isinstance(content, str):
        out.append(("text", summarize_text(content)))
        return out
    if isinstance(content, list):
        for block in content:
            if not isinstance(block, dict):
                out.append(("?", str(block)[:200]))
                continue
            t = block.get("type")
            if t == "text":
                out.append(("text", summarize_text(block.get("text",""))))
            elif t == "tool_use":
                name = block.get("name")
                inp = json.dumps(block.get("input", {}))
                out.append(("tool_use:"+str(name), summarize_text(inp, 300)))
            elif t == "tool_result":
                c = block.get("content")
                if isinstance(c, list):
                    txt = " ".join(b.get("text","") for b in c if isinstance(b, dict))
                else:
                    txt = str(c)
                err = block.get("is_error")
                out.append(("tool_result"+(" ERROR" if err else ""), summarize_text(txt, 300)))
            elif t == "thinking":
                out.append(("thinking", summarize_text(block.get("thinking",""), 200)))
            else:
                out.append((t, summarize_text(json.dumps(block), 200)))
    return out

path = sys.argv[1]
with open(path) as f:
    for i, line in enumerate(f):
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception as e:
            print(f"[{i}] PARSE ERROR: {e}")
            continue
        ts = obj.get("timestamp","")
        typ = obj.get("type")
        if typ in ("summary",):
            print(f"[{i}] SUMMARY: {obj.get('summary','')}")
            continue
        msg = obj.get("message")
        attachment = obj.get("attachment")
        if attachment:
            hn = attachment.get("hookName") or attachment.get("type")
            content = attachment.get("content","")
            print(f"[{i}] {ts} ATTACHMENT({hn}): {summarize_text(str(content),300)}")
            continue
        if not msg:
            print(f"[{i}] {ts} type={typ} (no message) keys={list(obj.keys())}")
            continue
        role = msg.get("role")
        content = msg.get("content")
        parts = content_summary(content)
        for kind, txt in parts:
            print(f"[{i}] {ts} {role} {kind}: {txt}")

import json, sys

def short(s, n=300):
    s = str(s)
    s = s.replace("\n", " \\n ")
    if len(s) > n:
        return s[:n] + f"...[{len(s)}chars]"
    return s

def summarize_input(tool_name, inp):
    if not isinstance(inp, dict):
        return short(inp)
    if tool_name == "Bash":
        return f"cmd={short(inp.get('command',''), 200)}"
    if tool_name in ("Read",):
        return f"file={inp.get('file_path')} offset={inp.get('offset')} limit={inp.get('limit')}"
    if tool_name in ("Edit",):
        return f"file={inp.get('file_path')} old={short(inp.get('old_string',''),100)}"
    if tool_name in ("Write",):
        return f"file={inp.get('file_path')} content_len={len(str(inp.get('content','')))}"
    if tool_name == "Grep":
        return f"pattern={short(inp.get('pattern',''),100)} path={inp.get('path')}"
    if tool_name == "Glob":
        return f"pattern={inp.get('pattern')} path={inp.get('path')}"
    if tool_name == "TodoWrite":
        todos = inp.get('todos', [])
        return f"todos={[t.get('content') for t in todos]}"
    if tool_name == "AskUserQuestion":
        return short(inp, 500)
    return short(inp, 250)

def main(path):
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except Exception as e:
                print(f"[PARSE ERROR: {e}]")
                continue
            typ = obj.get("type")
            ts = obj.get("timestamp", "")
            if typ == "queue-operation":
                print(f"{ts} QUEUE-OP {obj.get('operation')}: {short(obj.get('content',''), 200)}")
                continue
            if "attachment" in obj and obj.get("attachment"):
                att = obj["attachment"]
                print(f"{ts} ATTACHMENT hook={att.get('hookName')} event={att.get('hookEvent')}: {short(att.get('content',''), 200)}")
                continue
            message = obj.get("message")
            if message is None:
                # print raw keys for unknown entry types
                print(f"{ts} OTHER type={typ} keys={list(obj.keys())}")
                continue
            role = message.get("role")
            content = message.get("content")
            if isinstance(content, str):
                print(f"{ts} {role} TEXT: {short(content, 500)}")
                continue
            if isinstance(content, list):
                for block in content:
                    btype = block.get("type")
                    if btype == "text":
                        print(f"{ts} {role} TEXT: {short(block.get('text',''), 500)}")
                    elif btype == "tool_use":
                        name = block.get("name")
                        print(f"{ts} {role} TOOL_USE {name}: {summarize_input(name, block.get('input'))}")
                    elif btype == "tool_result":
                        c = block.get("content")
                        if isinstance(c, list):
                            texts = []
                            for cc in c:
                                if isinstance(cc, dict) and cc.get("type") == "text":
                                    texts.append(cc.get("text",""))
                            c = " ".join(texts)
                        is_err = block.get("is_error")
                        print(f"{ts} {role} TOOL_RESULT err={is_err}: {short(c, 400)}")
                    elif btype == "thinking":
                        print(f"{ts} {role} THINKING: {short(block.get('thinking',''), 200)}")
                    else:
                        print(f"{ts} {role} BLOCK({btype}): {short(block, 200)}")

if __name__ == "__main__":
    main(sys.argv[1])

import json, sys

def summarize_value(v, maxlen=200):
    if isinstance(v, str):
        s = v.replace("\n", " \\n ")
        return s[:maxlen] + ("..." if len(s) > maxlen else "")
    else:
        s = json.dumps(v)
        return s[:maxlen] + ("..." if len(s) > maxlen else "")

def summarize_input(tool_name, inp):
    if not isinstance(inp, dict):
        return summarize_value(inp)
    parts = []
    for k in ["command", "description", "file_path", "pattern", "url", "query", "skill", "prompt", "old_string", "new_string", "path"]:
        if k in inp:
            parts.append(f"{k}={summarize_value(inp[k], 150)}")
    if not parts:
        for k, v in list(inp.items())[:3]:
            parts.append(f"{k}={summarize_value(v, 100)}")
    return " ".join(parts)

def summarize_result(content):
    if isinstance(content, list):
        out = []
        for c in content:
            if isinstance(c, dict) and c.get("type") == "text":
                out.append(c.get("text", ""))
            else:
                out.append(json.dumps(c)[:200])
        content = "\n".join(out)
    if isinstance(content, str):
        s = content.replace("\n", " \\n ")
        return s[:300] + ("..." if len(s) > 300 else "")
    return summarize_value(content, 300)

path = sys.argv[1]
with open(path) as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        try:
            e = json.loads(line)
        except Exception as ex:
            print(f"PARSE_ERROR: {ex}")
            continue
        ts = e.get("timestamp", "")
        etype = e.get("type", "")
        if "attachment" in e and e.get("attachment"):
            att = e["attachment"]
            hookname = att.get("hookName", "")
            content = att.get("content", "")
            print(f"[{ts}] ATTACHMENT hook={hookname} content={summarize_value(content, 150)}")
            continue
        msg = e.get("message")
        if not msg:
            continue
        role = msg.get("role", "")
        content = msg.get("content")
        if isinstance(content, str):
            print(f"[{ts}] {role} TEXT: {summarize_value(content, 400)}")
            continue
        if isinstance(content, list):
            for c in content:
                ctype = c.get("type")
                if ctype == "text":
                    print(f"[{ts}] {role} TEXT: {summarize_value(c.get('text',''), 400)}")
                elif ctype == "tool_use":
                    name = c.get("name", "")
                    inp = c.get("input", {})
                    print(f"[{ts}] {role} TOOL_USE {name}: {summarize_input(name, inp)}")
                elif ctype == "tool_result":
                    is_err = c.get("is_error", False)
                    cont = c.get("content", "")
                    tag = "ERROR" if is_err else "OK"
                    print(f"[{ts}] {role} TOOL_RESULT[{tag}]: {summarize_result(cont)}")
                elif ctype == "thinking":
                    print(f"[{ts}] {role} THINKING: {summarize_value(c.get('thinking',''), 200)}")
                else:
                    print(f"[{ts}] {role} {ctype}: {summarize_value(c, 150)}")

